package org.kanger;
import java.util.*;
import org.kanger.ContextSignedUnaryExtensionSearch.*;
import org.kanger.ContextSignedUnaryExtensionSearch.Result;
import org.kanger.ContextSignedUnaryModel.Interpretation;
import org.kanger.ContextWitnessResultTransport.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
final class ContextSignedUnaryExtensionSearchMatrix {
 static int checks;static final int WORK=64000000;
 static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static Policy policy(){return new Policy(16,16,8,WORK,ContextSignedUnaryBranchMatrix.policy());}
 static void no(Result r,String why){require(r.status==Status.INCOMPLETE&&r.output==null,why+": no candidate prefix/conflict proof");}
 static void audit(Result r){require(r.status==Status.CONSTRUCTED_FINAL_UNARY&&r.output!=null,r.reason);ContextSignedUnaryBranchModel.Ledger l=r.output.ledger;ContextSignedUnaryBranchModelAudit.check(r.output,l.original,l.branch,l.extensions,l.policy,WORK);require(true,"independent final model freshly audited");}
 static ContextSignedUnaryModelAudit.Receipt expanded(ContextSignedUnaryBranchMatrix.Fixture f,boolean possible)throws Exception{Map<Cut,Interpretation> out=new LinkedHashMap<>();for(Map.Entry<Cut,Interpretation> e:f.models.entrySet()){Map<String,List<Boolean>> truth=new LinkedHashMap<>();for(Map.Entry<String,List<Boolean>> row:e.getValue().truth.entrySet())truth.put(row.getKey(),Arrays.asList(row.getValue().get(0),row.getValue().get(1),row.getValue().get(1)));if(e.getKey().equals(Cut.of(f.x)))truth.put("blocked",Arrays.asList(true,!possible,false));out.put(e.getKey(),new Interpretation(Arrays.asList(e.getValue().points.get(0),ContextSignedEligibilityMatrix.value(2)),truth,e.getValue().witnesses));}ContextSignedUnaryModel.Result r=ContextSignedUnaryModel.run(f.x,f.fs,out,f.original.ledger.policy);require(r.status==ContextSignedUnaryModel.Status.MODELLED_SUPPLIED_UNARY,r.reason);return r.output;}
 static void positive()throws Exception{
  ContextSignedUnaryBranchMatrix.Fixture negative=new ContextSignedUnaryBranchMatrix.Fixture(true);Result r=ContextSignedUnaryExtensionSearch.run(negative.original,negative.branch,policy());audit(r);require(r.tried==1,"negative new predicate constructed from false candidate");require(!r.output.ledger.extensions.get(Cut.of(negative.x)).truth.get("blocked").get(0),"actual negative product satisfied");require(r.output.ledger.original==negative.original&&r.output.ledger.branch==negative.branch,"exact actual receipts retained");
  ContextSignedUnaryBranchMatrix.Fixture imported=new ContextSignedUnaryBranchMatrix.Fixture(false);ContextSignedUnaryModelAudit.Receipt original=expanded(imported,true);r=ContextSignedUnaryExtensionSearch.run(original,imported.branch,policy());audit(r);require(r.tried==2,"false first imported denotation rejected then second concrete value found");require(r.output.ledger.extensions.get(Cut.of(imported.x)).denotations.values().contains(1),"imported Origin uses second named point");require(r.output.ledger.extensions.get(Cut.of(imported.a)).denotations.values().stream().allMatch(i->i==0),"original member binder assignment preserved across independent cuts");require(original.ledger.models.get(Cut.of(imported.x)).truth.get("blocked").get(0),"search did not overwrite original true cell");
  Snapshot x=ContextSignedUnaryBranchMatrix.bind(true,"!anchor(1); !$u seed(u);");Snapshot a=ContextSignedUnaryBranchMatrix.bind(false,"!@u seed(u)->mark(u);");Map<org.kanger.ContextProductionCapture.Source,Integer> w=Collections.singletonMap(x.primary.stream().filter(e->e.bundle!=null).findFirst().get().source,0);SemanticTermSnapshot one=ContextSignedUnaryModelMatrix.one();Map<Cut,Interpretation> models=ContextSignedUnaryBranchMatrix.models(x,ContextSignedUnaryBranchMatrix.m(one,w,"anchor",ContextSignedUnaryBranchMatrix.f(true,false),"seed",ContextSignedUnaryBranchMatrix.f(true,false)),a,ContextSignedUnaryBranchMatrix.m(one,w,"anchor",ContextSignedUnaryBranchMatrix.f(true,false),"seed",ContextSignedUnaryBranchMatrix.f(true,false),"mark",ContextSignedUnaryBranchMatrix.f(true,false)));ContextSignedUnaryModel.Result initial=ContextSignedUnaryModel.run(x,Collections.singletonList(a),models,ContextSignedUnaryModelMatrix.policy());require(initial.output!=null,initial.reason);ContextSignedWitnessNativeBranch.Result branch=ContextSignedWitnessNativeBranch.run(x,Collections.singletonList(a),ContextSignedWitnessNativeMatrix.policy());require(branch.output!=null&&branch.status==ContextSignedWitnessNativeBranch.Status.QUIESCENT_SUPPLIED,branch.reason);r=ContextSignedUnaryExtensionSearch.run(initial.output,branch.output,policy());audit(r);require(r.tried==2&&r.output.ledger.extensions.get(Cut.of(x)).truth.get("mark").get(0),"new positive predicate requires second truth candidate");require(r.output.ledger.extensions.get(Cut.of(x)).truth.get("mark").size()==2,"outside admissible class included in candidate truth vector");
  Snapshot universal=ContextSignedUnaryBranchMatrix.bind(false,"!@u mark(u);");Map<Cut,Interpretation> all=ContextSignedUnaryBranchMatrix.models(x,models.get(Cut.of(x)),universal,ContextSignedUnaryBranchMatrix.m(one,w,"anchor",ContextSignedUnaryBranchMatrix.f(true,false),"seed",ContextSignedUnaryBranchMatrix.f(true,false),"mark",ContextSignedUnaryBranchMatrix.f(true,true)));initial=ContextSignedUnaryModel.run(x,Collections.singletonList(universal),all,ContextSignedUnaryModelMatrix.policy());require(initial.output!=null,initial.reason);branch=ContextSignedWitnessNativeBranch.run(x,Collections.singletonList(universal),ContextSignedWitnessNativeMatrix.policy());require(branch.output!=null&&branch.status==ContextSignedWitnessNativeBranch.Status.QUIESCENT_SUPPLIED,branch.reason);r=ContextSignedUnaryExtensionSearch.run(initial.output,branch.output,policy());audit(r);require(r.tried==1&&r.output.ledger.extensions.get(Cut.of(x)).truth.isEmpty(),"foreign universal remains in its own cut, no invented self predicate truth");
  System.out.println("SIGNED_UNARY_EXTENSION_SEARCH_POSITIVE actualFinalAudited=true newSigns=true importedSecondPoint=true fixedOriginals=true");
 }
 static void boundary()throws Exception{
  ContextSignedUnaryBranchMatrix.Fixture f=new ContextSignedUnaryBranchMatrix.Fixture(false);ContextSignedUnaryModelAudit.Receipt original=expanded(f,true);Result r=ContextSignedUnaryExtensionSearch.run(original,f.branch,new Policy(1,16,8,WORK,ContextSignedUnaryBranchMatrix.policy()));no(r,"candidate cap before second imported assignment");require(r.tried==1&&r.reason.contains("Candidate limit"),"bounded search stops after exact first attempt");
  no(ContextSignedUnaryExtensionSearch.run(original,f.branch,new Policy(16,16,0,WORK,ContextSignedUnaryBranchMatrix.policy())),"imported Origin bound");no(ContextSignedUnaryExtensionSearch.run(original,f.branch,new Policy(16,16,8,1,ContextSignedUnaryBranchMatrix.policy())),"cumulative scan/construction work bound");no(ContextSignedUnaryExtensionSearch.run(original,f.branch,new Policy(16,16,8,WORK,new ContextSignedUnaryBranchModel.Policy(1,WORK,64))),"whole Source alternative obligation bound");no(ContextSignedUnaryExtensionSearch.run(original,f.branch,new Policy(16,16,8,WORK,new ContextSignedUnaryBranchModel.Policy(65536,1,64))),"fresh independent child audit work bound");
  ContextSignedUnaryBranchMatrix.Fixture newPredicate=new ContextSignedUnaryBranchMatrix.Fixture(true);no(ContextSignedUnaryExtensionSearch.run(newPredicate.original,newPredicate.branch,new Policy(16,0,8,WORK,ContextSignedUnaryBranchMatrix.policy())),"new truth cell bound includes outside");
  ContextSignedUnaryModelAudit.Receipt impossible=expanded(f,false);r=ContextSignedUnaryExtensionSearch.run(impossible,f.branch,policy());no(r,"no extension for GIVEN original named basis");require(r.tried==2&&r.reason.contains("space exhausted"),"finite two-point extension exhaustion never refutes original theory");
  no(ContextSignedUnaryExtensionSearch.run(null,f.branch,policy()),"missing model");ContextSignedUnaryBranchMatrix.Fixture other=new ContextSignedUnaryBranchMatrix.Fixture(false);no(ContextSignedUnaryExtensionSearch.run(original,other.branch,policy()),"different actual snapshot family");Object old=ContextSignedWitnessBarrierMatrix.replace(f.branch.termination.result,"output",f.branch.start);try{no(ContextSignedUnaryExtensionSearch.run(original,f.branch,policy()),"stale final scope");}finally{ContextSignedWitnessBarrierMatrix.replace(f.branch.termination.result,"output",old);}audit(ContextSignedUnaryExtensionSearch.run(original,f.branch,policy()));
  try{new Policy(65,16,8,WORK,ContextSignedUnaryBranchMatrix.policy());throw new AssertionError("unbounded candidates");}catch(IllegalArgumentException expected){require(true,"hard candidate cap");}
  System.out.println("SIGNED_UNARY_EXTENSION_SEARCH_BOUNDARY limitsAtomic=true exhaustionIncomplete=true noFixedTruthRewrite=true freshCurrentness=true");
 }
}
